@js:(function(){
  // 用 WebView 加载章节页，让站点自身的 JS 完成反爬挑战(challenge->unlock->正文)
  // BackstageWebView 会在 onPageFinished 后每秒执行本 JS 一次，返回空则重试(最多约30s)
  var js = "(function(){"
        + "var box=document.querySelector('#showReading .readChapterAppendBody');"
        + "if(!box){var b=document.querySelector('#showReading');box=b;}"
        + "if(!box)return '';"
        + "var t=box.innerHTML||'';"
        + "if(!t||t.indexOf('readGateLoading')>=0)return '';"
        + "if(t.indexOf('<p')<0&&t.replace(/<[^>]*>/g,'').trim().length<20)return '';"
        + "return t;"
        + "})()";
  return java.webView(null, baseUrl, js);
})()
